import React, { useEffect } from "react";
import { Avatar, Badge, Box, Divider, Fade, IconButton, Menu, MenuItem, Stack, styled, Tooltip, Typography, } from "@mui/material";
import { useTheme } from "@mui/material/styles";
import { CaretDown, MagnifyingGlass, Phone, VideoCamera } from "phosphor-react";
import useResponsive from "../../hooks/useResponsive";
import { ToggleSidebar } from "../../redux/slices/app";
import { useDispatch, useSelector } from "react-redux";
import { StartAudioCall } from "../../redux/slices/audioCall";
import { StartVideoCall } from "../../redux/slices/videoCall";
import { DeleteChat } from "../../redux/slices/conversation";

const StyledBadge = styled(Badge)(({ theme }) => ({
  "& .MuiBadge-badge": {
    backgroundColor: "#44b700",
    color: "#44b700",
    boxShadow: `0 0 0 2px ${theme.palette.background.paper}`,
    "&::after": {
      position: "absolute",
      top: 0,
      left: 0,
      width: "100%",
      height: "100%",
      borderRadius: "50%",
      animation: "ripple 1.2s infinite ease-in-out",
      border: "1px solid currentColor",
      content: '""',
    },
  },
  "@keyframes ripple": {
    "0%": {
      transform: "scale(.8)",
      opacity: 1,
    },
    "100%": {
      transform: "scale(2.4)",
      opacity: 0,
    },
  },
}));


const ChatHeader = () => {

  const user_id = window.localStorage.getItem("user_id");

  const dispatch = useDispatch();
  const isMobile = useResponsive("between", "md", "xs", "sm");
  const theme = useTheme();
  const { current_conversation } = useSelector((state) => state.conversation.direct_chat);
  const [conversationMenuAnchorEl, setConversationMenuAnchorEl] = React.useState(null);
  const openConversationMenu = Boolean(conversationMenuAnchorEl);
  const handleClickConversationMenu = (event) => { setConversationMenuAnchorEl(event.currentTarget); };
  const handleCloseConversationMenu = () => { setConversationMenuAnchorEl(null); };

  const Conversation_Menu = [
    {
      title: "Contact info",
      callback: () => { dispatch(ToggleSidebar()) }
    },
    {
      title: "Mute notifications",
      callback: () => { console.log("Clicked on Mute Notifications"); }
    },
    {
      title: "Delete chat",
      callback: () => {
        dispatch(DeleteChat({ room_id: current_conversation?.id, user_id: user_id }));
      }
    },
  ];


  return (
    <>
      <Box
        position={"relative"}
        zIndex={2}
        p={2}
        width={"100%"}
        sx={{
          backgroundColor:
            theme.palette.mode === "light"
              ? "#F8FAFF"
              : theme.palette.background,
          boxShadow: "0px 5px 10px rgba(0, 0, 0, 0.1)",
        }}
      >
        <Stack
          alignItems={"center"}
          direction={"row"}
          sx={{ width: "100%", height: "100%" }}
          justifyContent="space-between"
        >
          <Tooltip placement="bottom" title={"Profile"}>
            <Stack
              onClick={() => {
                dispatch(ToggleSidebar());
              }}
              spacing={2}
              direction="row"
              sx={{ cursor: 'pointer' }}
            >
              <Box>
                {current_conversation?.online ? (<StyledBadge
                  overlap="circular"
                  anchorOrigin={{
                    vertical: "bottom",
                    horizontal: "right",
                  }}
                  variant="dot"
                >
                  <Avatar
                    alt={current_conversation?.name}
                    src={current_conversation?.img}
                  />
                </StyledBadge>) : (
                  <Avatar
                    alt={current_conversation?.name}
                    src={current_conversation?.img}
                  />
                )
                }
              </Box>
              <Stack spacing={0.2} justifyContent={"center"}>
                <Typography variant="subtitle2">
                  {current_conversation?.name}
                </Typography>
                <Typography variant="caption">{current_conversation?.online ? "Online":"Offline"}</Typography>
              </Stack>
            </Stack>
          </Tooltip>
          <Stack
            direction={"row"}
            alignItems="center"
            spacing={isMobile ? 1 : 3}
          >
            <Tooltip placement="bottom" title={"Start Video Call"}>
              <IconButton onClick={() => {
                dispatch(StartVideoCall(current_conversation?.user_id));
              }}>
                <VideoCamera />
              </IconButton>
            </Tooltip>
            <Tooltip placement="bottom" title={"Start Audio Call"}>
              <IconButton
                onClick={() => {
                  dispatch(StartAudioCall(current_conversation?.user_id));
                }}
              >
                <Phone />
              </IconButton>
            </Tooltip>
            {!isMobile && (
              <Tooltip placement="bottom" title={"Search Messages"}>
                <IconButton>
                  <MagnifyingGlass />
                </IconButton>
              </Tooltip>
            )}
            <Divider orientation="vertical" flexItem />
            <IconButton
              id="conversation-positioned-button"
              aria-controls={
                openConversationMenu
                  ? "conversation-positioned-menu"
                  : undefined
              }
              aria-haspopup="true"
              aria-expanded={openConversationMenu ? "true" : undefined}
              onClick={handleClickConversationMenu}
            >
              <CaretDown />
            </IconButton>
            <Menu
              MenuListProps={{
                "aria-labelledby": "fade-button",
              }}
              TransitionComponent={Fade}
              id="conversation-positioned-menu"
              aria-labelledby="conversation-positioned-button"
              anchorEl={conversationMenuAnchorEl}
              open={openConversationMenu}
              onClose={handleCloseConversationMenu}
              anchorOrigin={{
                vertical: "bottom",
                horizontal: "right",
              }}
              transformOrigin={{
                vertical: "top",
                horizontal: "right",
              }}
            >
              <Box p={1}>
                <Stack spacing={1}>
                  {Conversation_Menu.map((el) => (
                    <MenuItem onClick={handleCloseConversationMenu}>
                      <Stack
                        sx={{ minWidth: 100 }}
                        direction="row"
                        alignItems={"center"}
                        justifyContent="space-between"
                        onClick={el.callback}
                      >
                        <span>{el.title}</span>
                      </Stack>{" "}
                    </MenuItem>
                  ))}
                </Stack>
              </Box>
            </Menu>
          </Stack>
        </Stack>
      </Box>
    </>
  );
};

export default ChatHeader;